import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.rQcsxYkC.js";const k=JSON.parse('{"title":"Ownership & transfers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ownership.md","filePath":"guide/ownership.md","lastUpdated":1785888355000}'),r={name:"guide/ownership.md"};function n(o,e,d,h,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="ownership-transfers" tabindex="-1">Ownership &amp; transfers <a class="header-anchor" href="#ownership-transfers" aria-label="Permalink to &quot;Ownership &amp; transfers&quot;">​</a></h1><p>Every <code>.arc</code> name is an ERC-721 token. Owning the token is owning the name. This page covers moving one to another wallet — and the reclaim step that trips almost everyone up the first time.</p><h2 id="what-you-own" tabindex="-1">What you own <a class="header-anchor" href="#what-you-own" aria-label="Permalink to &quot;What you own&quot;">​</a></h2><p>Registering mints a token whose ID is derived from the name itself:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tokenId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keccak256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><p>The ID is deterministic — the same name always maps to the same token ID, on any deployment. It is derived from the <strong>label</strong> (<code>alice</code>), not the full name (<code>alice.arc</code>).</p><p>The token lives in the registrar contract, which also stores the expiry. Standard ERC-721 interfaces apply: <code>ownerOf</code>, <code>transferFrom</code>, <code>safeTransferFrom</code>, <code>approve</code>, <code>setApprovalForAll</code>, plus <code>tokenURI</code> for metadata.</p><h2 id="two-kinds-of-ownership" tabindex="-1">Two kinds of ownership <a class="header-anchor" href="#two-kinds-of-ownership" aria-label="Permalink to &quot;Two kinds of ownership&quot;">​</a></h2><p>The thing to understand before transferring anything: a name has <strong>two</strong> owners recorded in two contracts, and they do different jobs.</p><table tabindex="0"><thead><tr><th></th><th>Where</th><th>Grants</th><th>Set by</th></tr></thead><tbody><tr><td><strong>Token owner</strong></td><td>Registrar (ERC-721)</td><td>The right to transfer, sell, and renew the name</td><td><code>transferFrom</code></td></tr><tr><td><strong>Registry owner</strong></td><td>Registry (the node)</td><td>The right to <strong>write records</strong></td><td><code>reclaim</code></td></tr></tbody></table><p><code>transferFrom</code> moves the token. It does <strong>not</strong> move the registry ownership.</p><p>At registration the controller sets both for you, so they start out identical and you never notice the distinction. A transfer breaks that alignment.</p><h2 id="reclaiming-after-a-transfer" tabindex="-1">Reclaiming after a transfer <a class="header-anchor" href="#reclaiming-after-a-transfer" aria-label="Permalink to &quot;Reclaiming after a transfer&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Reclaim immediately after receiving a name</p><p>Until the new token owner calls <code>reclaim</code>, the <strong>previous owner remains the registry owner</strong> and can still change the name&#39;s records — including the address it resolves to. The new owner&#39;s own writes revert with <code>!auth</code>.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">registrar.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reclaim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tokenId, newOwner)</span></span></code></pre></div><p>Anyone who is the token owner (or approved for it) can call this. Do it in the same session you receive the name.</p></div><p>This is not a bug — the two-layer design is inherited from ENS and lets a name be held by a contract while a different address manages its records. But for an ordinary transfer between two wallets, reclaim is a required second step.</p><p>The order that is safe:</p><ol><li>Sender: <code>transferFrom(sender, recipient, tokenId)</code></li><li>Recipient: <code>reclaim(tokenId, recipient)</code></li><li>Recipient: verify with <code>registry.owner(node) == recipient</code></li><li>Recipient: update records — in particular <code>setAddr</code>, which still points at the sender</li></ol><p>Step 4 matters. A transferred name keeps resolving to the <em>old</em> owner&#39;s address until the new owner overwrites it. Funds sent to the name in the meantime go to the previous owner.</p><h2 id="transferring-in-a-wallet" tabindex="-1">Transferring in a wallet <a class="header-anchor" href="#transferring-in-a-wallet" aria-label="Permalink to &quot;Transferring in a wallet&quot;">​</a></h2><p>Any ERC-721-capable wallet can transfer a name. You&#39;ll need the registrar address and the token ID — the app shows both. Send to the recipient&#39;s address as you would any NFT.</p><div class="warning custom-block"><p class="custom-block-title">A transfer is irreversible</p><p>There is no undo, no clawback and no support desk. Sending to a wrong address loses the name permanently. Sending to a contract that can&#39;t handle ERC-721 tokens loses it just as permanently — prefer <code>safeTransferFrom</code>, which reverts rather than stranding the token.</p><p>Verify the recipient address character by character, or send to a <code>.arc</code> name you have resolved and confirmed.</p></div><h2 id="approvals" tabindex="-1">Approvals <a class="header-anchor" href="#approvals" aria-label="Permalink to &quot;Approvals&quot;">​</a></h2><p>To let another address or contract move your name:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">approve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tokenId)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// one name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setApprovalForAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ok)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// every name you hold</span></span></code></pre></div><p>Listing on the <a href="/docs/guide/marketplace.html">marketplace</a> requires an approval, because the market transfers the token on your behalf when a sale settles.</p><div class="warning custom-block"><p class="custom-block-title">setApprovalForAll is broad and lasting</p><p>It authorises the operator over <strong>every name you currently hold and every name you register in future</strong>, until you revoke it. Only grant it to contracts you have reason to trust, and revoke it when you&#39;re done. Prefer per-token <code>approve</code> where you can.</p></div><p>Approvals are cleared automatically on transfer, so a sale doesn&#39;t leave a stale approval behind.</p><h2 id="expiry-interacts-with-ownership" tabindex="-1">Expiry interacts with ownership <a class="header-anchor" href="#expiry-interacts-with-ownership" aria-label="Permalink to &quot;Expiry interacts with ownership&quot;">​</a></h2><p><code>registrar.ownerOf(id)</code> <strong>reverts with <code>expired</code></strong> once the expiry has passed — including during the 90-day grace period. It does not return the previous owner.</p><p>Two consequences:</p><ul><li><strong>Don&#39;t use <code>ownerOf</code> as a liveness check</strong> unless you&#39;re catching the revert. Use <code>nameExpires(id)</code> and compare against the current block timestamp.</li><li><strong>A name in grace cannot be transferred or sold</strong>, because every operation that calls <code>ownerOf</code> reverts. <a href="/docs/guide/renewals.html">Renew it first</a>, then transfer.</li></ul><p>The token itself is never burned on expiry — the internal owner mapping survives, which is what lets a renewal during grace restore full function.</p><h2 id="transfers-and-your-primary-name" tabindex="-1">Transfers and your primary name <a class="header-anchor" href="#transfers-and-your-primary-name" aria-label="Permalink to &quot;Transfers and your primary name&quot;">​</a></h2><p>If you transfer away the name you use as your <a href="/docs/guide/primary-name.html">primary name</a>, the round-trip verification breaks and apps fall back to displaying your address. Set a different primary name you still own.</p><h2 id="watching-transfers" tabindex="-1">Watching transfers <a class="header-anchor" href="#watching-transfers" aria-label="Permalink to &quot;Watching transfers&quot;">​</a></h2><p>Transfers emit the standard ERC-721 event:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">event</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Transfer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> indexed</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> tokenId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>A mint is a <code>Transfer</code> from the zero address. The indexer tracks these and exposes them as <code>kind: &quot;transfer&quot;</code> activity items — see <a href="/docs/api/endpoints.html#activity">API endpoints</a>.</p><h2 id="revert-reference" tabindex="-1">Revert reference <a class="header-anchor" href="#revert-reference" aria-label="Permalink to &quot;Revert reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Revert</th><th>Cause</th></tr></thead><tbody><tr><td><code>!auth</code></td><td>Writing records without being the registry owner. Call <code>reclaim</code>.</td></tr><tr><td><code>expired</code></td><td><code>ownerOf</code> on a name past its expiry, including during grace.</td></tr><tr><td><code>none</code></td><td><code>ownerOf</code> on a token that was never minted.</td></tr><tr><td><code>!live</code></td><td>The registrar no longer controls the <code>.arc</code> node. Protocol-level fault.</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/marketplace.html">Marketplace</a> — selling instead of transferring.</li><li><a href="/docs/guide/records.html">Records &amp; profile</a> — updating records after a transfer.</li><li><a href="/docs/safety.html">Safety</a> — before you move a name that matters.</li></ul>`,42)])])}const g=t(r,[["render",n]]);export{k as __pageData,g as default};
